import java.util.*;

public class Solution {

	public static void main(String[] args) {
		Scanner in = new Scanner(System.in);
		int g = in.nextInt();
		JumpQueue jq = new JumpQueue(g);

		in.nextLine();

		for (int i = 0; i < g; i++) {
			String s = in.nextLine();
			jq.setGroup(s, i);
		}

		String line = in.nextLine();
		jq.setEvents(line);
		jq.ans();
	}
}

class JumpQueue {
	int t; // number of groups
	List<Queue<Integer>> listOfQueue = new ArrayList<>();
	Map<Integer, Integer> map = new HashMap<>(); // groupID : value
	List<Integer> idList = new ArrayList<>();
	StringBuilder sb = new StringBuilder();

	public JumpQueue(int t) {
		this.t = t;
	}

	public void ans() {
		System.out.println(sb);
	}

	public void setEvents(String line) {
		String[] ss = line.split("\\s+");
		for (String s : ss) {
			int v = Integer.parseInt(s);
			if (v == -1) {
				dequeue();
			} else {
				enqueue(v);
			}
		}
	}

	public void dequeue() {
		for (Queue<Integer> team : listOfQueue) {
			if (!team.isEmpty()) {
				int v = team.poll();
				sb.append(v).append("\n");

				if (team.isEmpty()) {
					listOfQueue.remove(0);
					idList.remove(0);
				}
				break;
			}
		}
	}

	public void enqueue(int v) {
		Integer id = map.get(v);

		if (id == null) {
			map.put(v, t);
			id = t;
			t++;

			// lonely wolf join queue at the tail
			Queue<Integer> team = new LinkedList<>();
			team.add(v);
			listOfQueue.add(team);
			idList.add(id);

			return;
		}

		boolean found = false;
		for (int i = 0; i < idList.size(); i++) {
			if (idList.get(i) == id) {
				found = true;
				Queue<Integer> team = listOfQueue.get(i);
				team.add(v);
				break;
			}
		}
		if (!found) {
			Queue<Integer> team = new LinkedList<>();
			team.add(v);
			listOfQueue.add(team);
			idList.add(id);
		}
	}

	public void setGroup(String s, int id) {
		String[] ss = s.split("\\s+");

		for (int i = 0; i < ss.length; i++) {
			int v = Integer.parseInt(ss[i]);
			map.put(v, id);
		}
	}
}
